export interface KoeApiErrorOptions {
  status: number;
  title: string;
  type?: string;
  detail?: string;
  instance?: string;
}

export class KoeApiError extends Error {
  readonly status: number;
  readonly title: string;
  readonly type: string;
  readonly detail?: string;
  readonly instance?: string;

  constructor(options: KoeApiErrorOptions) {
    super(options.detail ?? options.title);
    this.name = "KoeApiError";
    this.status = options.status;
    this.title = options.title;
    this.type = options.type ?? "about:blank";
    this.detail = options.detail;
    this.instance = options.instance;
  }
}

export interface KoeClientOptions {
  baseUrl: string;
  apiPrefix?: string;
  token?: string;
  fetch?: typeof globalThis.fetch;
}

const DEFAULT_API_PREFIX = "/api/v1";

function normalizeApiPrefix(apiPrefix: string | undefined): string {
  const prefix = apiPrefix?.trim();
  if (!prefix || prefix === "/") {
    return DEFAULT_API_PREFIX;
  }
  const withLeadingSlash = prefix.startsWith("/") ? prefix : `/${prefix}`;
  return withLeadingSlash.endsWith("/")
    ? withLeadingSlash.slice(0, -1)
    : withLeadingSlash;
}

export interface KoeClient {
  auth: {
    anonymous(): Promise<AnonymousAuthResponse>;
    me(token?: string): Promise<User>;
    updateMe(body: UpdateProfileBody, token?: string): Promise<User>;
  };
  threads: {
    getByRef(
      ref: string,
      query?: GetThreadByRefQuery,
      token?: string
    ): Promise<ThreadResponse>;
    react(
      threadId: string,
      emoji: string,
      token?: string
    ): Promise<Reaction | null>;
    unreact(threadId: string, emoji: string, token?: string): Promise<void>;
  };
  comments: {
    list(
      threadId: string,
      query?: CommentListQuery,
      token?: string
    ): Promise<CommentListResponse>;
    create(
      threadId: string,
      body: CreateCommentBody,
      token?: string
    ): Promise<Comment>;
    vote(
      commentId: string,
      value: VoteValue,
      token?: string
    ): Promise<Vote | null>;
    unvote(commentId: string, token?: string): Promise<void>;
    react(
      commentId: string,
      emoji: string,
      token?: string
    ): Promise<Reaction | null>;
    unreact(commentId: string, emoji: string, token?: string): Promise<void>;
    report(commentId: string, reason: string, token?: string): Promise<Report>;
  };
  moderation: {
    queue(token?: string): Promise<ModerationQueueResponse>;
    actions(token?: string): Promise<ModerationActionListResponse>;
    act(
      commentId: string,
      action: CommentModerationActionVerb,
      token?: string
    ): Promise<Comment>;
    ban(userId: string, token?: string): Promise<User>;
    suspend(userId: string, token?: string): Promise<User>;
  };
}

interface RequestOptions {
  method: string;
  token?: string;
  query?: Record<string, string | number | undefined>;
  body?: unknown;
}

function buildUrl(
  baseUrl: string,
  apiPrefix: string | undefined,
  path: string,
  query?: Record<string, string | number | undefined>
): string {
  const normalizedBase = baseUrl
    ? baseUrl.endsWith("/")
      ? baseUrl
      : `${baseUrl}/`
    : typeof window !== "undefined"
      ? `${window.location.origin}/`
      : "http://localhost/";

  const prefix = normalizeApiPrefix(apiPrefix);
  const relativePath = path.startsWith("/") ? path.slice(1) : path;
  const fullPath = `${prefix.slice(1)}/${relativePath}`;

  const url = new URL(fullPath, normalizedBase);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined) {
        url.searchParams.set(key, String(value));
      }
    }
  }
  return url.toString();
}

export function createKoeClient(options: KoeClientOptions): KoeClient {
  const fetchFn = options.fetch ?? globalThis.fetch;

  async function request<S extends ZodTypeAny>(
    schema: S,
    path: string,
    requestOptions: RequestOptions
  ): Promise<z.output<S>> {
    const { method, token, query, body } = requestOptions;
    const headers: Record<string, string> = {};
    const effectiveToken = token ?? options.token;
    if (effectiveToken) {
      headers.authorization = `Bearer ${effectiveToken}`;
    }
    if (body !== undefined) {
      headers["content-type"] = "application/json";
    }

    const response = await fetchFn(
      buildUrl(options.baseUrl, options.apiPrefix, path, query),
      {
        method,
        headers,
        body: body !== undefined ? JSON.stringify(body) : undefined,
      }
    );

    if (!response.ok) {
      let problem: Record<string, unknown> = {};
      try {
        problem = (await response.json()) as Record<string, unknown>;
      } catch {
        // Ignore non-JSON error responses.
      }
      throw new KoeApiError({
        status: response.status,
        title:
          typeof problem.title === "string" ? problem.title : "Request failed",
        type: typeof problem.type === "string" ? problem.type : undefined,
        detail:
          typeof problem.detail === "string" ? problem.detail : undefined,
        instance:
          typeof problem.instance === "string" ? problem.instance : undefined,
      });
    }

    if (response.status === 204) {
      return undefined as unknown as z.output<S>;
    }

    const data: unknown = await response.json();
    return schema.parse(data);
  }

  function moderateUser(
    userId: string,
    action: UserModerationActionVerb,
    token?: string
  ): Promise<User> {
    return request(UserSchema, "/moderation/actions", {
      method: "POST",
      body: { userId, action },
      token,
    });
  }

  return {
    auth: {
      anonymous: () =>
        request(AnonymousAuthResponseSchema, "/auth/anonymous", {
          method: "POST",
        }),
      me: (token) =>
        request(UserSchema, "/auth/me", { method: "GET", token }),
      updateMe: (body, token) =>
        request(UserSchema, "/auth/me", { method: "PATCH", body, token }),
    },
    threads: {
      getByRef: (ref, query, token) =>
        request(
          ThreadResponseSchema,
          `/threads/by-ref/${encodeURIComponent(ref)}`,
          { method: "GET", query, token }
        ),
      react: async (threadId, emoji, token) => {
        const result = await request(
          ReactionSchema,
          `/threads/${threadId}/reactions`,
          { method: "POST", body: { emoji }, token }
        );
        return result ?? null;
      },
      unreact: async (threadId, emoji, token) => {
        await request(
          ReactionSchema,
          `/threads/${threadId}/reactions/${encodeURIComponent(emoji)}`,
          { method: "DELETE", token }
        );
      },
    },
    comments: {
      list: (threadId, query, token) =>
        request(
          CommentListResponseSchema,
          `/threads/${threadId}/comments`,
          { method: "GET", query, token }
        ),
      create: (threadId, body, token) =>
        request(CommentSchema, `/threads/${threadId}/comments`, {
          method: "POST",
          body,
          token,
        }),
      vote: async (commentId, value, token) => {
        const result = await request(
          VoteSchema,
          `/comments/${commentId}/vote`,
          { method: "POST", body: { value }, token }
        );
        return result ?? null;
      },
      unvote: async (commentId, token) => {
        await request(VoteSchema, `/comments/${commentId}/vote`, {
          method: "DELETE",
          token,
        });
      },
      react: async (commentId, emoji, token) => {
        const result = await request(
          ReactionSchema,
          `/comments/${commentId}/reactions`,
          { method: "POST", body: { emoji }, token }
        );
        return result ?? null;
      },
      unreact: async (commentId, emoji, token) => {
        await request(
          ReactionSchema,
          `/comments/${commentId}/reactions/${encodeURIComponent(emoji)}`,
          { method: "DELETE", token }
        );
      },
      report: (commentId, reason, token) =>
        request(ReportSchema, `/comments/${commentId}/reports`, {
          method: "POST",
          body: { reason },
          token,
        }),
    },
    moderation: {
      queue: (token) =>
        request(ModerationQueueResponseSchema, "/moderation/queue", {
          method: "GET",
          token,
        }),
      actions: (token) =>
        request(
          ModerationActionListResponseSchema,
          "/moderation/actions",
          { method: "GET", token }
        ),
      act: (commentId, action, token) =>
        request(CommentSchema, "/moderation/actions", {
          method: "POST",
          body: { commentId, action },
          token,
        }),
      ban: (userId, token) => moderateUser(userId, "ban", token),
      suspend: (userId, token) => moderateUser(userId, "suspend", token),
    },
  };
}